// ===== Reach & Frequency Calculator (Measure › Reach & Frequency) — v37 =====
["rf_setup","rf_reports","rf_pulls","rf_perf"].forEach(c => { if (!COLS.includes(c)) { COLS.push(c); S[c] = S[c] || []; } });
const CALC_TILES = [["setup","Setup","reporting cadence · sources · partner windows"],["audience","Audience","universe · bounds · segments · markets"],["assumptions","Assumptions","rates · modifiers · vendor vs research"],["weekly","Inputs · Weekly","one report per reporting week"],["monthly","Inputs · Monthly","one report per month"],["dedup","Deduplication","DCM divisor · Sainsbury"],["perf","Performance","by market · combined · your tables"]];
const calcPlan = () => byId("mplans", V.calcPlan) || null;
function rfSetup(P) { return live("rf_setup").find(s => s.plan_id === P.id) || {plan_id: P.id, campaign_id: P.campaign_id, client_id: P.client_id, cadence: {weekly: false, monthly: true}, sources: {}, windows: {}, locked: false}; }
function rfActuals(P, cad) { let A = live("actuals").find(a => a.plan_id === P.id && (a.cadence || "monthly") === cad); if (!A) { A = {plan_id: P.id, campaign_id: P.campaign_id, cadence: cad, periods: rfPeriods(P, cad).map(p => p.key), rows: {}, dcm: {}}; S.actuals.push(A); } const keys = rfPeriods(P, cad).map(p => p.key); if (!A.periods?.length || A.periods.length !== keys.length || A.periods[0] !== keys[0]) A.periods = keys; return A; }
function rfPartners(P) { return [...new Set(P.lines.filter(l => l.impressions).map(l => cleanName(l.partner)))]; }
function rfWindowHint(p) { const q = siteKB(p).filter(h => h.kind === "questionnaire").pop()?.data; const t = norm((q?.rf_reporting || "") + " " + (q?.tagging || "") + " " + (q?.period || "")); if (!q) return {hint: "no questionnaire — ask before locking", value: "monthly"}; const w = /weekly/.test(t), m = /monthly/.test(t), f = /flight|cumulative/.test(t); return {hint: q.rf_reporting?.slice(0, 120) || q.tagging?.slice(0, 120) || "", value: w && m ? "both" : w ? "weekly" : f && !m ? "flight" : "monthly"}; }
function rfExpectedSources(P, SU) { const srcs = {}; for (const p of rfPartners(P)) { const l = P.lines.find(x => cleanName(x.partner) === p); const k = SU.sources[p] || rfSourceFor(p, l.channel); const b = bucketFor(l.partner, l.channel).bucket; if (b.startsWith("Modelled") || b.startsWith("No reach")) continue; (srcs[k] ||= []).push(p); } srcs.cm360_pull = ["DCM deduplicated pull"]; return srcs; }
function rfReportName(P, cad, per) { const c = byId("clients", P.client_id); const k = byId("campaigns", P.campaign_id); const fl = P.lines.map(l => parseFlight(l.flight)).filter(Boolean); const fs = fl.map(f => f.start).sort()[0], fe = fl.map(f => f.end).sort().pop(); const s = fs && per.start < fs ? fs : per.start, e = fe && per.end > fe ? fe : per.end; return `${c?.client_name || c?.name || ""} - ${c?.lob || ""} - ${k?.name || ""} - RF ${cad === "weekly" ? "Weekly" : "Monthly"} - ${s} to ${e}`; }
function rfReport(P, cad, per) { return live("rf_reports").find(r => r.plan_id === P.id && r.cadence === cad && r.period_key === per.key) || null; }
async function rfReportDraft(P, cad, per) { let r = rfReport(P, cad, per); if (!r) r = await put("rf_reports", {plan_id: P.id, campaign_id: P.campaign_id, client_id: P.client_id, cadence: cad, period_key: per.key, period_start: per.start, period_end: per.end, name: rfReportName(P, cad, per), status: "draft", slots: {}, notes: ""}); return r; }
function rfMissing(P, cad, per, SU) { const r = rfReport(P, cad, per); const exp = rfExpectedSources(P, SU); return Object.keys(exp).filter(k => !r?.slots?.[k]).map(k => ({src: k, label: RF_SOURCES[k]?.label || k, partners: exp[k]})); }
// ---- page
function pRF() { const plans = live("mplans").filter(inWs).filter(p => p.lines?.some(l => l.impressions)).sort((a, b) => (wsName(byId("clients", a.client_id)) + (byId("campaigns", a.campaign_id)?.name || "")).localeCompare(wsName(byId("clients", b.client_id)) + (byId("campaigns", b.campaign_id)?.name || "")) || b.version - a.version); const preferred = plans.filter(p => (byId("clients", p.client_id)?.name || "").toLowerCase().indexOf("demo") < 0 && p.lines.some(l => parseFlight(l.flight))); const P = calcPlan() || (V.ws ? (preferred[0] || plans[0]) : null); if (P && !V.calcPlan) V.calcPlan = P.id; const tile = V.calcTile || "setup"; const SU = P ? rfSetup(P) : null;
  const tiles = CALC_TILES.filter(([k]) => !(k === "weekly" && !SU?.cadence?.weekly) && !(k === "monthly" && !SU?.cadence?.monthly));
  const state = k => { if (!P) return "todo"; if (k === tile) return "cur"; if (k === "setup") return SU.locked ? "done" : "todo"; if (k === "weekly" || k === "monthly") { const pers = rfPeriods(P, k); const done = pers.filter(per => rfReport(P, k, per)?.status === "final").length; return done === pers.length && pers.length ? "done" : done ? "part" : "todo"; } if (k === "audience") return live("audiences").some(a => a.kind === "internal_research") ? "done" : "todo"; if (k === "assumptions") { try { return registerChecks(registerRows(P)).missing.length ? "part" : "done"; } catch (e) { return "todo"; } } if (k === "dedup") return Object.values(rfActuals(P, SU.cadence.weekly && !SU.cadence.monthly ? "weekly" : "monthly").dcm || {}).some(x => x) ? "done" : "todo"; if (k === "perf") return live("rf_perf").some(x => x.plan_id === P.id) ? "done" : "todo"; return "todo"; };
  const strip = `<div class="dstages" style="grid-template-columns:repeat(${tiles.length},minmax(0,1fr))">${tiles.map(([k, t, d], i) => { const st = state(k); return `<div class="dstage ${st === "part" ? "cur" : st}" data-a="calc_tile" data-v="${k}" title="${esc(d)}" style="cursor:pointer;${st === "part" ? "background:var(--warn-bg);border-color:var(--warn)" : ""}"><span class="n">${st === "done" ? "✓" : i + 1}</span><span class="t">${t}</span><span class="s">${esc(d)}</span></div>`; }).join("")}</div>`;
  return `<div class="topbar"><h1>Reach & Frequency</h1>${helpPanel("rf")}<span class="lab">the calculator: one plan, every number from setup to the client tables</span><span class="spacer"></span><select id="calc_plan" class="inp">${plans.map(p => `<option value="${p.id}" ${P?.id === p.id ? "selected" : ""}>${esc(wsName(byId("clients", p.client_id)))} · ${esc(p.name)} v${p.version}</option>`).join("") || `<option value="">no plans with impressions in this workspace</option>`}</select></div>
  ${!P && !V.ws ? `<div class="card"><b>Choose a workspace or a plan</b><div class="lab">The calculator works on one plan at a time. Pick a Client - Line of Business in the top left, or choose a plan from the list above.</div></div>` : ""}${P ? strip + (tile === "setup" ? calcSetup(P, SU) : tile === "audience" ? calcAudience(P) : tile === "assumptions" ? calcAssumptions(P) : tile === "weekly" || tile === "monthly" ? calcInputs(P, SU, tile) : tile === "dedup" ? calcDedup(P, SU) : calcPerf(P, SU)) : `<div class="card lab">Upload a media plan with impressions in Plan → Plans, then come back here.</div>`}`; }
// ---- Setup: cadence, sources, partner windows (the lock-down pop-up)
function calcSetup(P, SU) { const partners = rfPartners(P); const lineOf = p => P.lines.find(l => cleanName(l.partner) === p);
  return `<div class="grid"><div class="card s5"><b>Reporting cadence</b><div class="lab">Which grains the client report needs. Weekly answers pacing and repeat rate; monthly answers reach. Both may be on.</div><label style="display:block;font-size:13px;margin-top:6px"><input type="checkbox" data-su="cadence.weekly" ${SU.cadence.weekly ? "checked" : ""} ${SU.locked ? "disabled" : ""}> Weekly reporting</label><label style="display:block;font-size:13px"><input type="checkbox" data-su="cadence.monthly" ${SU.cadence.monthly ? "checked" : ""} ${SU.locked ? "disabled" : ""}> Monthly reporting</label><div class="lab" style="margin-top:8px">Flight ${rfPeriods(P, "monthly")[0]?.start} → ${rfPeriods(P, "monthly").at(-1)?.end} · ${rfPeriods(P, "weekly").length} reporting weeks · ${rfPeriods(P, "monthly").length} months</div>
    <div style="margin-top:12px">${SU.locked ? `<div class="find documented"><b class="lvl">LOCKED</b><div>Reporting setup locked ${SU.locked_at || ""}. Inputs tiles are generated from it. <button class="btn ghost xs" data-a="su_unlock">Unlock to change</button></div></div>` : `<button class="btn" data-a="su_lock">Lock reporting setup…</button><div class="lab">Locking asks you to confirm each partner's reporting period against what they said in their questionnaire.</div>`}</div></div>
  <div class="card s7"><b>Where each partner's reporting comes from</b><div class="lab">The system already knows how to read each source (column map in RF_SOURCES, or a mapping you saved). Pick the source per partner; the Inputs tiles get one upload slot per source per period.</div><table><thead><tr><th>Partner</th><th>Channel · bucket</th><th>Reporting source</th><th>Unit reported</th></tr></thead><tbody>${partners.map(p => { const l = lineOf(p); const b = bucketFor(l.partner, l.channel).bucket; const k = SU.sources[p] || rfSourceFor(p, l.channel); const mod = b.startsWith("Modelled") || b.startsWith("No reach"); return `<tr><td><b>${esc(p)}</b></td><td class="lab">${esc(l.channel)} · ${pill(b.slice(0, 24), b.startsWith("In the DCM") ? "ok" : mod ? "bad" : "warn")}</td><td>${mod ? `<span class="lab">no report expected — stays modelled</span>` : `<select class="inp xs" data-susrc="${esc(p)}" ${SU.locked ? "disabled" : ""}>${Object.entries(RF_SOURCES).filter(([kk]) => kk !== "cm360_pull").map(([kk, s]) => `<option value="${kk}" ${k === kk ? "selected" : ""}>${esc(s.label)}</option>`).join("")}</select>`}</td><td class="lab" style="font-size:11px">${mod ? "" : esc(RF_SOURCES[k]?.unit || "")}</td></tr>`; }).join("")}<tr><td><b>DCM deduplicated pull</b></td><td class="lab">all tagged placements</td><td class="lab">CM360 · one report per period — the number nothing else can derive</td><td class="lab" style="font-size:11px">modelled people</td></tr></tbody></table></div>
  ${V.suLockOpen ? `<div class="card s12" style="border-color:var(--accent)"><div class="topbar"><b>Confirm each partner's reporting period</b><span class="lab">from the questionnaire answers on file · this is what the Inputs tiles will expect</span><span class="spacer"></span><button class="btn ghost sm" data-a="su_lock_cancel">Cancel</button><button class="btn sm" data-a="su_lock_confirm">Confirm and lock</button></div><table><thead><tr><th>Partner</th><th>What they told us</th><th>Reporting period</th><th>Flight-to-date unique available?</th></tr></thead><tbody>${partners.map(p => { const l = lineOf(p); const b = bucketFor(l.partner, l.channel).bucket; if (b.startsWith("Modelled") || b.startsWith("No reach")) return `<tr><td><b>${esc(p)}</b></td><td class="lab" colspan="3">modelled — never reports; stays at the modelled figure</td></tr>`; const h = rfWindowHint(p); const cur = SU.windows[p] || h.value; return `<tr><td><b>${esc(p)}</b></td><td style="font-size:11px">${esc(h.hint)}</td><td><select class="inp xs" data-suwin="${esc(p)}">${[["weekly","weekly"],["monthly","monthly"],["both","weekly and monthly"],["flight","flight-to-date only"]].map(([v, n]) => `<option value="${v}" ${cur === v ? "selected" : ""}>${n}</option>`).join("")}</select></td><td><select class="inp xs" data-suftd="${esc(p)}"><option value="yes" ${SU.ftd?.[p] !== "no" ? "selected" : ""}>yes</option><option value="no" ${SU.ftd?.[p] === "no" ? "selected" : ""}>no</option></select></td></tr>`; }).join("")}</tbody></table><div class="lab">A partner whose period is coarser than the cadence you chose (monthly partner, weekly report) will show as "not expected this week" rather than missing.</div></div>` : ""}</div>`; }
// ---- Audience
function calcAudience(P) { const R = live("audiences").filter(a => a.kind === "internal_research" && (a.client_id === P.client_id || !a.client_id)).sort((a, b) => b.as_of.localeCompare(a.as_of))[0]; const U = R?.universe || 800000, UB = R?.bay || Math.round(U * 0.037875); const rows = registerRows(P); const thr = planThreshold(P); const bounds = live("defaults").filter(d => d.metric === "universe_count" && !d.valid_to && !/adult population/i.test(d.answers_question)); const geo = live("defaults").filter(d => d.metric === "geo_index" && !d.valid_to && (d.geography || "").startsWith("CBSA")).sort((a, b) => b.value - a.value); const mk = l => /san fran|sf|bay/i.test(l.market) ? "SF Bay" : /event/i.test(l.market) ? "Event" : (/^(us|usa|national|)$/i.test((l.market || "").trim()) ? "National" : (l.market || "").trim()); const tot = P.lines.reduce((a, l) => a + (l.impressions || 0), 0);
  const segs = {}; rows.forEach(r => { const k = SEG_CLASS(r.line); (segs[k] ||= {imps: 0, lines: 0, partners: new Set(), pools: []}); segs[k].imps += r.line.impressions || 0; segs[k].lines++; segs[k].partners.add(cleanName(r.line.partner)); if (r.cells.pool_size.value) segs[k].pools.push([cleanName(r.line.partner), r.cells.pool_size.value, r.cells.pool_period.value, r.cells.pool_size.tier]); });
  const mks = {}; P.lines.forEach(l => { const k = mk(l); (mks[k] ||= {imps: 0, lines: 0}); mks[k].imps += l.impressions || 0; mks[k].lines++; });
  return `<div class="grid"><div class="card s5"><b>Universe · ${esc(thr)} investable, individuals</b><div class="big">${fmt(U)}</div><div class="lab">SF Bay slice ${fmt(UB)} (${(UB / U * 100).toFixed(2)}% of national) · ${R ? `chosen ${R.as_of} from ${R.sources.length} sources — the conservative end, not the midpoint` : "no internal research on file — upload the Reach Calculator (Audience tab)"}</div>${R ? `<table><thead><tr><th>Source</th><th>Unit</th><th>Threshold</th><th class="num">At ${esc(thr)}</th><th>Use</th></tr></thead><tbody>${R.sources.map(s => `<tr><td>${esc(s.source)}</td><td>${esc(s.unit)}</td><td>${esc(s.threshold)}</td><td class="num mono">${fmt(s.figure)}</td><td>${pill(s.use, /^yes/i.test(s.use) ? "ok" : "info")}</td></tr>`).join("")}</tbody></table>` : ""}<div class="lab" style="margin-top:6px">Rule: the universe is never modified by a modifier; sub-geographies are slices, never additions.</div></div>
  <div class="card s7"><b>Bounds and confirmations · published research on file</b><div class="lab">Different bases answer different questions — never blend vendors in one plan.</div><table><thead><tr><th>Figure</th><th class="num">Count</th><th>Unit · threshold</th><th>Status</th><th>Source · vintage</th></tr></thead><tbody>${bounds.map(d => `<tr><td style="font-size:12px">${esc(d.answers_question.slice(0, 70))}</td><td class="num mono">${fmt(d.value)}</td><td class="lab">${esc(d.audience_unit || "")} · ${esc(d.threshold || "")}</td><td>${pill(d.status, d.status === "VERIFIED" ? "ok" : d.status === "DERIVED" ? "info" : "warn")}</td><td style="font-size:11px"><a href="${esc(d.source_url)}" target="_blank" rel="noopener">${esc(d.source_name.slice(0, 40))}</a> · ${esc(String(d.source_vintage))}</td></tr>`).join("") || `<tr><td colspan="5" class="lab">No universe counts in the library.</td></tr>`}</tbody></table></div>
  <div class="card s6"><b>By segment · how people got into the segment</b><div class="lab">${Object.keys(segs).length} classes across ${P.lines.length} lines</div><table><thead><tr><th>Segment class</th><th class="num">Lines</th><th class="num">Share of impressions</th><th>Partners</th><th>Stated pools (partner · pool · period · tier)</th></tr></thead><tbody>${Object.entries(segs).sort((a, b) => b[1].imps - a[1].imps).map(([k, v]) => `<tr><td><b>${esc(k)}</b></td><td class="num">${v.lines}</td><td class="num mono">${(v.imps / tot * 100).toFixed(1)}%</td><td class="lab" style="font-size:11px">${[...v.partners].map(esc).join(", ")}</td><td style="font-size:11px">${v.pools.slice(0, 5).map(([p, s, per, t]) => `${esc(p)} ${fmt(s)} ${esc(per || "?")} <span class="tier ${t || "none"}">${t || "no tier"}</span>`).join("<br>")}</td></tr>`).join("")}</tbody></table><div class="lab">Partner-sum test: a stated pool larger than the universe means one of you is wrong — it may be used as a pool but never as evidence about the universe.</div></div>
  <div class="card s6"><b>By market</b><table><thead><tr><th>Market</th><th class="num">Universe</th><th class="num">Lines</th><th class="num">Impressions</th><th class="num">Impressions per person</th><th>Read</th></tr></thead><tbody>${Object.entries(mks).map(([k, v]) => { const u = k === "SF Bay" ? UB : k === "National" ? U : null; const ipp = u ? v.imps / u : null; return `<tr><td><b>${k}</b></td><td class="num mono">${u ? fmt(u) : "—"}</td><td class="num">${v.lines}</td><td class="num mono">${fmt(v.imps)}</td><td class="num mono">${ipp ? ipp.toFixed(0) : "—"}</td><td class="lab" style="font-size:11px">${ipp && ipp > 100 ? "saturates on any sourced basis — pace on frequency, not reach" : ipp ? "reach is a live number here" : (k === "Event" ? "events: exposures, outside both universes" : "no universe defined for this market yet — set one in Audiences")}</td></tr>`; }).join("")}</tbody></table><b style="font-size:13px;display:block;margin-top:8px">Metro concentration on file</b><table><thead><tr><th>CBSA</th><th class="num">Index</th><th class="num">Share of national $200k+</th></tr></thead><tbody>${geo.slice(0, 8).map(d => `<tr><td style="font-size:11px">${esc(d.metro || d.geography)}</td><td class="num mono">${d.value}</td><td class="num mono">${d.share_national != null ? (d.share_national * 100).toFixed(2) + "%" : ""}</td></tr>`).join("")}</tbody></table><div class="lab">$200k+ income share is a proxy for the wealth distribution, not the distribution itself.</div></div></div>`; }
// ---- Assumptions
function calcAssumptions(P) { const rows = registerRows(P); const chk = registerChecks(rows); const res = resolveAll(P, rows); const M = V.meas || {divisor: 1.4, universe: live("audiences").find(a => a.kind === "internal_research")?.universe || 800000}; const partners = rfPartners(P);
  const cmp = partners.map(p => { const l = P.lines.find(x => cleanName(x.partner) === p); const q = siteKB(p).filter(h => h.kind === "questionnaire").pop()?.data; const r = rows.find(x => cleanName(x.line.partner) === p); const seg = SEG_CLASS(l), pc = PLATFORM_CLASS(l); const dOn = currentDefaults("on_target_rate", {segment_class: seg, channel: CH_CLASS(l), threshold: planThreshold(P)})[0]; const dDev = currentDefaults("device_ratio", {publisher: pc})[0]; const dReach = currentDefaults("reachability_pct", {})[0]; const reachStated = q?.reachability?.match(/(\d{1,3})\s?%/)?.[1]; return {p, seg, pc, on: r?.cells.on_target_rate, dOn, dev: r?.cells.device_ratio, dDev, reachStated: reachStated ? +reachStated / 100 : null, reachText: q?.reachability || "", dReach, figure: q?.figure || "", pool: r?.cells.pool_size, freq: r?.cells.frequency, freqCap: q?.freq_cap || ""}; });
  return `<div class="grid"><div class="card s12"><div class="topbar"><b>Assumptions · every modifier in the model</b><span class="lab">${chk.missing.length ? pill(chk.missing.length + " without provenance", "bad") : pill("all inputs tiered", "ok")} · edit any value in the plan's Register (rationale required, logged) · locks survive re-upload</span><span class="spacer"></span><button class="btn ghost sm" data-a="calc_reg" data-v="${P.id}">Open the Register</button></div>
  <div class="frow"><label class="lab">Deduplication divisor (pre-flight floor)<br><input class="inp" id="as_div" value="${M.divisor}" style="width:80px"></label><label class="lab">Universe<br><input class="inp" id="as_u" value="${M.universe}" style="width:110px"></label><button class="btn ghost sm" data-a="as_apply">Apply to model</button><span class="lab">the divisor moves to the measured figure from the Deduplication tile at ~week 4</span></div></div>
  <div class="card s12"><b>Vendor-reported vs third-party research · per partner</b><div class="lab">What the partner said (T1) beside the library default for that segment class and platform (T3/T4). A vendor value always beats a default; the comparison is a sanity check, never an average.</div><div class="scroll"><table><thead><tr><th>Partner</th><th>Segment class · platform class</th><th>Audience the partner quoted</th><th class="num">On-target in model</th><th class="num">Library grid</th><th class="num">Device ratio in model</th><th class="num">Library</th><th>Reachability stated</th><th class="num">Library</th><th class="num">Pool · period</th><th class="num">Frequency</th><th>Cap policy</th></tr></thead><tbody>${cmp.map(x => { const gap = x.on?.value != null && x.dOn ? x.on.value / x.dOn.value : null; return `<tr><td><b>${esc(x.p)}</b></td><td class="lab" style="font-size:11px">${esc(x.seg)}<br>${esc(x.pc)}</td><td style="font-size:11px">${esc(x.figure.slice(0, 90))}</td><td class="num mono">${x.on?.value != null ? (x.on.value * 100).toFixed(2) + "%" : "—"} <span class="tier ${x.on?.tier || "none"}">${x.on?.tier || "—"}</span></td><td class="num mono">${x.dOn ? (x.dOn.value * 100).toFixed(2) + "%" : "no cell"}${gap && (gap > 1.5 || gap < 0.67) ? ` <span class="pill warn">${gap.toFixed(1)}× the grid</span>` : ""}</td><td class="num mono">${x.dev?.value ?? "—"} <span class="tier ${x.dev?.tier || "none"}">${x.dev?.tier || "—"}</span></td><td class="num mono">${x.dDev ? x.dDev.value + (x.dDev.value_low != null ? ` (${x.dDev.value_low}–${x.dDev.value_high})` : "") : "—"}</td><td style="font-size:11px">${x.reachStated != null ? `<b>${(x.reachStated * 100).toFixed(0)}%</b> · ` : ""}${esc(x.reachText.slice(0, 70))}</td><td class="num mono">${x.dReach ? (x.dReach.value * 100).toFixed(0) + "% (T5)" : "—"}</td><td class="num mono">${x.pool?.value != null ? fmt(x.pool.value) + " · " + esc(x.pool?.value != null ? (rows.find(r => cleanName(r.line.partner) === x.p)?.cells.pool_period.value || "?") : "") : "—"}</td><td class="num mono">${x.freq?.value ?? "—"} <span class="tier ${x.freq?.tier || "none"}">${x.freq?.tier || "—"}</span></td><td style="font-size:11px">${esc(x.freqCap.slice(0, 50))}</td></tr>`; }).join("")}</tbody></table></div></div>
  <div class="card s12"><b>Where each input landed on its fallback chain</b><div class="lab">rung 1 = the partner's own statement at our threshold; the higher the rung, the weaker the evidence.</div><div class="scroll"><table><thead><tr><th>Partner · line</th>${["on_target_rate","reachability_pct","device_ratio","frequency","pool_size"].map(m => `<th>${m.replace(/_/g, " ")}</th>`).join("")}</tr></thead><tbody>${rows.map(r => `<tr><td style="font-size:11px"><b>${esc(cleanName(r.line.partner))}</b> · ${esc(r.line.placement.slice(0, 32))}</td>${["on_target_rate","reachability_pct","device_ratio","frequency","pool_size"].map(m => { const x = res.find(y => y.key === r.key && y.metric === m); return `<td style="font-size:11px">${x ? `<span class="tier ${x.tier || "none"}">${x.tier || "—"}</span> rung ${x.rung}${x.violations.length ? ` <span class="pill warn" title="${esc(x.violations[0])}">!</span>` : ""}` : ""}</td>`; }).join("")}</tr>`).join("")}</tbody></table></div></div></div>`; }
