async function calcExportPeriod(P, SU, cad, pi) { const periods = rfPeriods(P, cad); const per = periods[pi]; const A = rfActuals(P, cad); const R = reconcile(P, A); const rep = rfReport(P, cad, per); const missing = rfMissing(P, cad, per, SU); const wb = XLSX.utils.book_new(); const add = (n, rows) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows), n.slice(0, 31)); add("Cover", [[rfReportName(P, cad, per)], ["Status", rep?.status || "draft"], ["Period", per.start, per.end], ["Universe", R.U], ["Divisor floor", R.floor], ["Rolling divisor", R.rolling || ""], ["Missing sources", missing.map(m => m.label).join("; ") || "none"], ["Notes", rep?.notes || ""]]); add("Inputs", [["Partner","Impressions","Unique reach","Flight-to-date unique","Source","Flag"], ...rfPartners(P).map(p => { const l = P.lines.find(x => cleanName(x.partner) === p); const k = SU.sources[p] || rfSourceFor(p, l.channel); return [p, A.rows[p]?.imps?.[pi] ?? "", A.rows[p]?.reach?.[pi] ?? "", A.rows[p]?.ftd_reach ?? "", RF_SOURCES[k]?.label || k, missing.some(m => m.src === k) ? "MISSING SOURCE" : ""]; }), ["DCM deduplicated pull", "", A.dcm[pi] ?? "", "", "CM360", missing.some(m => m.src === "cm360_pull") ? "MISSING" : ""]]); add("Dedup Center", [["Period","Sum in-pull reach","DCM pull","Divisor","Publisher/platform reach (union on top)","Period reach","Cumulative","% of universe"], ...R.per.map((x, i) => [x.period, x.sumIn, x.dcm, x.divisor, x.pubRep, x.periodReach, x.periodReach != null ? R.cum[i] : "", x.periodReach != null ? R.cum[i] / R.U : ""])]); const D = perfData(P, SU); for (const mk of ["National","SF Bay","Combined"]) add(mk, [["Metric", ...D.periods.map(p => p.label)], ...PERF_METRICS.map(([k, n]) => [n, ...D.out[mk][k]])]); const out = XLSX.write(wb, {bookType: "xlsx", type: "array"}); const dl = await claude.use("downloads"); const name = rfReportName(P, cad, per).replace(/[^\w\- ]/g, "") + ".xlsx"; if (dl) { try { await dl.save({filename: name, data: new Blob([out])}); } catch (e) { toast("Download declined"); } } else Object.assign(document.createElement("a"), {href: URL.createObjectURL(new Blob([out])), download: name}).click(); }
async function calcExportPerf(P, SU) { const D = perfData(P, SU); const wb = XLSX.utils.book_new(); const add = (n, rows) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows), n.slice(0, 31)); for (const mk of ["National","SF Bay","Combined"]) add(mk, [["Metric", ...D.periods.map(p => p.label)], ...PERF_METRICS.map(([k, n]) => [n, ...D.out[mk][k]])]); for (const d of live("rf_perf").filter(x => x.plan_id === P.id)) add(d.name, [["Metric", ...D.periods.map(p => p.label)], ...(d.metrics || []).map(k => [PERF_METRICS.find(x => x[0] === k)?.[1] || k, ...D.periods.map((_, i) => d.cells?.[`${k}|${i}`] ?? D.out[d.market][k][i])])]); const out = XLSX.write(wb, {bookType: "xlsx", type: "array"}); const c = byId("clients", P.client_id); const name = `${c?.client_name || ""} - ${c?.lob || ""} - ${byId("campaigns", P.campaign_id)?.name || ""} - RF Performance - ${today()}`.replace(/[^\w\- ]/g, "") + ".xlsx"; const dl = await claude.use("downloads"); if (dl) { try { await dl.save({filename: name, data: new Blob([out])}); } catch (e) { toast("Download declined"); } } else Object.assign(document.createElement("a"), {href: URL.createObjectURL(new Blob([out])), download: name}).click(); }
async function calcApplyUpload(P, SU, cad, pi, srcKey, u) { const periods = rfPeriods(P, cad); const per = periods[pi]; const saved = live("rf_maps").find(m => m.client_id === P.client_id && m.header_hash === u.header_hash); const R = rfParseUpload(u, srcKey, periods, saved); const A = rfActuals(P, cad); const partners = rfPartners(P); let n = 0; const un = []; for (const r of R.rows) { if (r.reach_conflict) continue; if (r.pi !== pi && r.pi >= 0) continue; if (!r.partner && srcKey === "cm360_pull") { A.dcm[pi] = r.reach; n++; continue; } const m = partners.find(p => cleanName(r.partner) === p) || partners.find(p => norm(r.partner).includes(norm(p)) || norm(p).includes(norm(r.partner).split(" ")[0])); if (!m) { un.push(r.partner); continue; } (A.rows[m] ||= {imps: [], reach: []}); if (r.imps != null) A.rows[m].imps[pi] = Math.round(r.imps); if (r.reach != null) A.rows[m].reach[pi] = Math.round(r.reach); n++; } const doc = live("actuals").find(x => x.plan_id === P.id && (x.cadence || "monthly") === cad && x.id); if (doc) { const before = {...doc}; Object.assign(doc, A); await put("actuals", doc, "update", before); } else await put("actuals", A); const rep = await rfReportDraft(P, cad, per); const before = {...rep}; rep.slots = {...(rep.slots || {}), [srcKey]: u.id}; rep.slot_meta = {...(rep.slot_meta || {}), [srcKey]: {at: today(), cells: n, problems: R.problems.concat(un.length ? ["unmatched partners: " + [...new Set(un)].join(", ")] : [])}}; await put("rf_reports", rep, "update", before); await logChange({event: "rf-input", plan_id: P.id, campaign_id: P.campaign_id, field: RF_SOURCES[srcKey]?.label || srcKey, to: `${per.label}: ${n} cell(s) from ${u.filename}`, rationale: un.length ? "unmatched: " + [...new Set(un)].join(", ") : "all partners matched"}); toast(`${per.label}: ${n} cell(s) applied${un.length ? " · unmatched " + [...new Set(un)].join(", ") : ""}`); }
