  if (t.id === "calc_file") { const f = t.files[0]; if (!f || !V.calcSlot) return; const u = await calcUploadFile(f); await calcApplyUpload(P, rfSetup(P), V.calcSlot.cad, V.calcSlot.pi, V.calcSlot.src, u); render(); return; }
